/**
 * Deterministic local hole filling behind a segmented subject. When the compositor
 * moves or scales the real subject, the original subject area of the background
 * would otherwise show a ghost duplicate. Pixels inside the dilated SAM mask are
 * replaced by a normalized convolution of the surrounding background only:
 *   fill = blur(img · (1 − m)) / blur(1 − m)
 * evaluated at the finest scale with enough support. Nothing is generated by a model
 * and pixels outside the dilated mask are returned byte-identical.
 */

export interface FillOptions {
  /** Grow the subject mask by this many pixels before filling (covers edge halos). */
  dilatePx: number;
  /** Gaussian sigma of the finest normalized-convolution level, in pixels. */
  blurSigma: number;
}

const MASK_THRESHOLD = 128;
/** Minimum normalized-convolution support accepted at a level before trying a coarser one. */
const MIN_SUPPORT = 0.12;
const INF = 1e20;

/** Exact squared Euclidean distance (Felzenszwalb–Huttenlocher), in place on one line. */
function edt1d(f: Float64Array, n: number, d: Float64Array, v: Int32Array, z: Float64Array): void {
  let k = 0;
  v[0] = 0; z[0] = -INF; z[1] = INF;
  for (let q = 1; q < n; q++) {
    let s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    while (s <= z[k]) { k--; s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]); }
    k++; v[k] = q; z[k] = s; z[k + 1] = INF;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (z[k + 1] < q) k++;
    d[q] = (q - v[k]) * (q - v[k]) + f[v[k]];
  }
}

/**
 * Squared Euclidean distance from every pixel to the nearest pixel where `isSource`
 * is true. Pixels that are sources have distance 0. Deterministic O(width·height).
 */
export function squaredDistanceTransform(isSource: (index: number) => boolean, width: number, height: number): Float64Array {
  const size = Math.max(width, height);
  const f = new Float64Array(size), d = new Float64Array(size), z = new Float64Array(size + 1);
  const v = new Int32Array(size);
  const out = new Float64Array(width * height);
  for (let i = 0; i < out.length; i++) out[i] = isSource(i) ? 0 : INF;
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) f[y] = out[y * width + x];
    edt1d(f, height, d, v, z);
    for (let y = 0; y < height; y++) out[y * width + x] = d[y];
  }
  for (let y = 0; y < height; y++) {
    const row = y * width;
    for (let x = 0; x < width; x++) f[x] = out[row + x];
    edt1d(f, width, d, v, z);
    for (let x = 0; x < width; x++) out[row + x] = d[x];
  }
  return out;
}

/** Binary dilation of a 0/255 (thresholded at 128) mask by a Euclidean radius. Returns 0/1 bytes. */
export function dilateMask(mask: Uint8Array, width: number, height: number, radius: number): Uint8Array {
  const out = new Uint8Array(width * height);
  if (radius <= 0) { for (let i = 0; i < out.length; i++) out[i] = mask[i] >= MASK_THRESHOLD ? 1 : 0; return out; }
  const distance = squaredDistanceTransform((i) => mask[i] >= MASK_THRESHOLD, width, height);
  const limit = radius * radius;
  for (let i = 0; i < out.length; i++) out[i] = distance[i] <= limit ? 1 : 0;
  return out;
}

/** Binary erosion (pixels at least `radius` inside the mask). Returns 0/1 bytes. */
export function erodeMask(mask: Uint8Array, width: number, height: number, radius: number): Uint8Array {
  const distance = squaredDistanceTransform((i) => mask[i] < MASK_THRESHOLD, width, height);
  const out = new Uint8Array(width * height);
  const limit = radius * radius;
  for (let i = 0; i < out.length; i++) out[i] = mask[i] >= MASK_THRESHOLD && distance[i] > limit ? 1 : 0;
  return out;
}

/** Box widths whose three-pass convolution approximates a Gaussian of `sigma`. */
function boxRadii(sigma: number): number[] {
  const passes = 3;
  const ideal = Math.sqrt(12 * sigma * sigma / passes + 1);
  let lower = Math.floor(ideal); if (lower % 2 === 0) lower--;
  const upper = lower + 2;
  const m = Math.round((12 * sigma * sigma - passes * lower * lower - 4 * passes * lower - 3 * passes) / (-4 * lower - 4));
  return Array.from({ length: passes }, (_, i) => ((i < m ? lower : upper) - 1) / 2);
}

/** One zero-padded box pass along rows (horizontal) or columns. Constant divisor keeps the ratio exact. */
function boxPass(src: Float32Array, dst: Float32Array, width: number, height: number, radius: number, horizontal: boolean): void {
  if (radius < 1) { dst.set(src); return; }
  const scale = 1 / (2 * radius + 1);
  const lines = horizontal ? height : width, length = horizontal ? width : height;
  const stride = horizontal ? 1 : width;
  for (let line = 0; line < lines; line++) {
    const base = horizontal ? line * width : line;
    let sum = 0;
    for (let i = 0; i <= Math.min(radius, length - 1); i++) sum += src[base + i * stride];
    for (let i = 0; i < length; i++) {
      dst[base + i * stride] = sum * scale;
      const add = i + radius + 1, remove = i - radius;
      if (add < length) sum += src[base + add * stride];
      if (remove >= 0) sum -= src[base + remove * stride];
    }
  }
}

/** Zero-padded Gaussian approximation (3 box passes per axis), in place via a scratch buffer. */
export function gaussianBlurZero(data: Float32Array, width: number, height: number, sigma: number, scratch = new Float32Array(data.length)): Float32Array {
  if (sigma <= 0) return data;
  for (const radius of boxRadii(sigma)) {
    boxPass(data, scratch, width, height, radius, true);
    boxPass(scratch, data, width, height, radius, false);
  }
  return data;
}

function assertGeometry(rgba: Uint8Array, mask: Uint8Array, width: number, height: number, options: FillOptions): void {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1 || width * height > 40_000_000) throw new Error("Fill geometry is invalid.");
  if (rgba.length !== width * height * 4 || mask.length !== width * height) throw new Error("Fill buffers do not match the declared geometry.");
  if (!(options.dilatePx >= 0 && options.dilatePx <= 512) || !(options.blurSigma > 0 && options.blurSigma <= 512)) throw new Error("Fill options are out of range.");
}

/**
 * Replaces the dilated subject region with background-only normalized convolution.
 * `rgba` is straight (non-premultiplied) RGBA; `mask` is one byte per pixel (subject ≥ 128).
 * Returns a new buffer; pixels outside the dilated mask are copied unchanged.
 */
export function fillBehindSubject(rgba: Uint8Array, mask: Uint8Array, width: number, height: number, options: FillOptions): Buffer {
  assertGeometry(rgba, mask, width, height, options);
  const out = Buffer.from(rgba);
  const hole = dilateMask(mask, width, height, options.dilatePx);
  const n = width * height;
  let pending = 0;
  for (let i = 0; i < n; i++) pending += hole[i];
  if (!pending) return out;

  const known = new Float32Array(n);
  const sums = [new Float32Array(n), new Float32Array(n), new Float32Array(n)];
  const mean = [0, 0, 0];
  let knownCount = 0;
  for (let i = 0; i < n; i++) {
    if (hole[i]) continue;
    known[i] = 1; knownCount++;
    for (let c = 0; c < 3; c++) { sums[c][i] = rgba[i * 4 + c]; mean[c] += rgba[i * 4 + c]; }
  }
  const filled = new Uint8Array(n);
  const scratch = new Float32Array(n);
  const weight = new Float32Array(n), channel = new Float32Array(n);
  const limit = Math.max(width, height);
  // Coarse-to-fine is unnecessary: each hole pixel takes the finest level with support,
  // so detail near the hole boundary is kept and only deep interior pixels average widely.
  for (let sigma = options.blurSigma; pending > 0 && knownCount > 0 && sigma <= limit * 2; sigma *= 2) {
    weight.set(known); gaussianBlurZero(weight, width, height, sigma, scratch);
    const accepted: number[] = [];
    for (let i = 0; i < n; i++) if (hole[i] && !filled[i] && weight[i] >= MIN_SUPPORT) accepted.push(i);
    if (!accepted.length) continue;
    for (let c = 0; c < 3; c++) {
      channel.set(sums[c]); gaussianBlurZero(channel, width, height, sigma, scratch);
      for (const i of accepted) out[i * 4 + c] = Math.max(0, Math.min(255, Math.round(channel[i] / weight[i])));
    }
    for (const i of accepted) { out[i * 4 + 3] = 255; filled[i] = 1; }
    pending -= accepted.length;
  }
  // No background support at any scale (subject covers almost everything): neutral mean.
  const fallback = knownCount ? mean.map((value) => Math.round(value / knownCount)) : [128, 128, 128];
  if (pending > 0) for (let i = 0; i < n; i++) if (hole[i] && !filled[i]) { out[i * 4] = fallback[0]; out[i * 4 + 1] = fallback[1]; out[i * 4 + 2] = fallback[2]; out[i * 4 + 3] = 255; }
  return out;
}
